on conflict (category, slug) do update set
  label            = excluded.label,
  description      = excluded.description,
  has_page         = true,
  glossary_visible = true;

do $$
declare
  described_count integer;
  page_count integer;
begin
  select count(*) into described_count
  from tags
  where glossary_visible = true and description is not null;

  select count(*) into page_count
  from tags
  where glossary_visible = true
    and description is not null
    and has_page is distinct from false;

  raise notice 'Glossary sync complete: % described terms, % page-eligible terms',
    described_count, page_count;
end $$;
